# Classic nonfiction (memoir, science, travel) and essays & speeches, Grades 4–12.
from spec_a import P

# ---------------- Memoir, science and travel ----------------
P('keller', 'keller', 'We walked down the path to the well-house', 'each name gave birth to a new thought.', 'The Story of My Life', 'Helen Keller', 1903, [
  ('What did Helen’s teacher spell into her hand?', 'The word water', ['Her own name', 'The word teacher', 'The word honeysuckle'], 'She “spelled into the other the word water, first slowly, then rapidly.”'),
  ('Why was this moment so important to Helen?', 'She suddenly understood that words name things', ['She learned to swim', 'She could hear for the first time', 'She found her lost doll'], '“Somehow the mystery of language was revealed to me.”'),
  ('Helen could not see or hear. How did she learn the word?', 'Through touch — water on one hand, letters spelled into the other', ['By reading a book', 'By listening to her teacher', 'By watching other children'], 'The water gushed “over one hand” while her teacher spelled into the other.'),
  ('What does “That living word awakened my soul” mean?', 'Understanding language made her feel alive and free', ['She woke up from a nap', 'The water was very cold', 'She began to speak aloud'], 'It “gave it light, hope, joy, set it free!”'),
  ('How did Helen feel as she left the well-house?', 'Eager to learn', ['Tired and confused', 'Afraid of water', 'Bored with lessons'], '“I left the well-house eager to learn.”'),
])
P('candle', 'faraday', 'I purpose, in return for the honour you do us', 'were it even so good.', 'The Chemical History of a Candle', 'Michael Faraday', 1861, [
  ('What is the subject of Faraday’s lectures?', 'The chemical history of a candle', ['How to make candles', 'The history of electricity', 'Why the sun shines'], 'He will bring before them “the Chemical History of a Candle.”'),
  ('Why does Faraday say he would happily repeat this subject every year?', 'It is so interesting and connects to many areas of science', ['It is the only topic he knows', 'His audience asked him to', 'Candles were new at the time'], '“So abundant is the interest that attaches itself to the subject.”'),
  ('What does Faraday claim about a simple candle?', 'Studying it opens the door to all of natural science', ['It is the most dangerous invention', 'It will soon be replaced', 'It is too simple to study'], '“There is no more open door by which you can enter into the study of natural philosophy.”'),
  ('In 1861, “natural philosophy” meant …', 'science, especially physics and chemistry', ['religion', 'history', 'poetry'], 'Science was then called natural philosophy — the study of nature.'),
  ('What is Faraday’s purpose in this opening?', 'To convince his audience that an everyday object is worth studying', ['To sell candles', 'To warn about fire', 'To tell a funny story'], 'He trusts he “shall not disappoint” them by choosing the candle.'),
])
P('franklin', 'franklin', 'I walked up the street, gazing about till near the market-house', 'a most awkward, ridiculous appearance.', 'The Autobiography of Benjamin Franklin', 'Benjamin Franklin', 1791, [
  ('What did young Franklin buy at the baker’s?', 'Three great puffy rolls', ['A three-penny loaf', 'A bag of biscuits', 'A cake for Miss Read'], '“He gave me, accordingly, three great puffy rolls.”'),
  ('Why was he surprised?', 'He got much more bread than he expected for his money', ['The bread was stale', 'The baker gave it free', 'The rolls were tiny'], 'He did not know “the greater cheapness” of bread in Philadelphia; “I was surpris’d at the quantity.”'),
  ('Why did he carry a roll under each arm?', 'He had no room in his pockets', ['To keep them warm', 'To share with friends', 'To show them off'], '“Having no room in my pockets, walk’d off with a roll under each arm.”'),
  ('Who saw him and thought he looked ridiculous?', 'Miss Read, who would later become his wife', ['The baker', 'A boy with bread', 'His brother'], 'He passed “the door of Mr. Read, my future wife’s father,” and she saw him from the door.'),
  ('What tone does Franklin use about his younger self?', 'Gently humorous', ['Angry', 'Tragic', 'Boastful'], 'He laughs at his “most awkward, ridiculous appearance.”'),
])
P('tortoise', 'beagle', 'The inhabitants believe that these animals are absolutely deaf', 'very difficult to keep my balance.', 'The Voyage of the Beagle', 'Charles Darwin', 1839, [
  ('Which animals is Darwin describing on the Galápagos Islands?', 'Giant tortoises', ['Iguanas', 'Sea turtles', 'Finches'], 'He calls them “these great monsters” with shells.'),
  ('What did the tortoises do when Darwin passed them?', 'Pulled in their head and legs, hissed, and dropped to the ground', ['Ran away quickly', 'Bit his boots', 'Followed him'], 'It “would draw in its head and legs, and uttering a deep hiss fall to the ground.”'),
  ('What did Darwin do to make a tortoise walk with him on it?', 'Rapped on the back of its shell', ['Fed it cactus', 'Pulled its tail', 'Shouted in its ear'], '“Giving a few raps on the hinder part of their shells, they would rise up and walk away.”'),
  ('What kind of writing is this?', 'A scientist’s first-hand observations', ['A fairy tale', 'A poem', 'A newspaper advertisement'], 'Darwin records what he himself saw and did.'),
  ('Why might the local people believe the tortoises were deaf?', 'They did not notice people walking close behind them', ['They had no ears', 'They lived underwater', 'A doctor tested them'], '“Certainly they do not overhear a person walking close behind them.”'),
])
P('upfromslavery', 'washington', 'I swept the recitation-room three times.', 'gave him more genuine satisfaction.', 'Up from Slavery', 'Booker T. Washington', 1901, [
  ('Why did Washington clean the room so carefully?', 'He felt his future depended on impressing the teacher', ['He was paid by the hour', 'He loved cleaning', 'He was being punished'], '“My future depended upon the impression I made upon the teacher.”'),
  ('How did the head teacher check his work?', 'She rubbed her handkerchief over the woodwork and furniture', ['She asked other students', 'She counted the benches', 'She looked from the doorway'], 'She “took her handkerchief and rubbed it on the woodwork.”'),
  ('What did the teacher finally say?', '“I guess you will do to enter this institution.”', ['“Clean it again tomorrow.”', '“You missed a spot.”', '“You may go home now.”'], 'When she found no dirt, she “quietly remarked, ‘I guess you will do to enter this institution.’”'),
  ('Why does Washington call the sweeping “my college examination”?', 'It was the test that got him admitted to school', ['He studied cleaning in college', 'The exam was held in that room', 'He was joking about Harvard'], 'Passing it let him enter the institution.'),
  ('What does this passage show about Washington?', 'He was determined and hard-working', ['He was lazy', 'He was afraid of teachers', 'He wanted to give up'], 'Sweeping three times and dusting four times shows his determination.'),
])
P('river', 'mississippi', 'Now when I had mastered the language of this water', 'when steamboating was new to me.', 'Life on the Mississippi', 'Mark Twain', 1883, [
  ('What has Twain learned to do?', 'Read every feature of the river like a pilot', ['Swim across the river', 'Build steamboats', 'Paint sunsets'], 'He “had mastered the language of this water.”'),
  ('What did he gain, and what did he lose?', 'He gained expert knowledge but lost the river’s beauty and poetry', ['He gained money but lost his boat', 'He gained friends but lost his home', 'He gained nothing and lost nothing'], '“I had made a valuable acquisition. But I had lost something, too.”'),
  ('“The language of this water” is a metaphor meaning …', 'the signs on the river’s surface that a pilot learns to read', ['a foreign language spoken on boats', 'the sound of the waves', 'a book about rivers'], 'Like letters of an alphabet, the river’s features carry meaning.'),
  ('Why does Twain remember a sunset from when “steamboating was new” to him?', 'Back then he could still see the river’s beauty', ['It was his first day of work', 'A boat sank that day', 'He painted it'], 'Before he knew the river as a pilot, he saw “the grace, the beauty, the poetry.”'),
  ('What is the central idea of the passage?', 'Expert knowledge can take away the wonder of something', ['Rivers are dangerous', 'Sunsets are best on rivers', 'Steamboats are beautiful'], '“All the grace, the beauty, the poetry had gone out of the majestic river!”'),
])

# ---------------- Essays and speeches ----------------
P('bank', 'leacock', 'When I go into a bank I get rattled.', 'My voice was sepulchral.', 'My Financial Career (Literary Lapses)', 'Stephen Leacock (Canadian)', 1910, [
  ('What makes the narrator nervous?', 'Going into a bank', ['Speaking in public', 'Going to school', 'Riding a train'], '“When I go into a bank I get rattled.”'),
  ('Why did he go to the bank anyway?', 'His salary had been raised and he wanted to save it', ['He needed a loan', 'He worked there', 'A friend dared him'], '“My salary had been raised to fifty dollars a month and I felt that the bank was the only place for it.”'),
  ('What does “rattled” mean here?', 'Nervous and flustered', ['Shaken like a toy', 'Angry', 'Very rich'], 'Everything in the bank makes him lose his calm.'),
  ('How does Leacock create humour in the opening?', 'By exaggerating how panicked an ordinary errand makes him', ['By telling jokes about money', 'By describing a robbery', 'By making fun of the clerks'], 'He becomes “an irresponsible idiot” just by crossing the threshold.'),
  ('“My voice was sepulchral” means his voice sounded …', 'deep and gloomy, like from a tomb', ['high and squeaky', 'loud and cheerful', 'fast and confident'], 'Sepulchral comes from sepulchre, a tomb — a funny word for a nervous voice.'),
])
P('declaration', 'declaration', 'When in the Course of human events', 'to provide new Guards for their future security.', 'The Declaration of Independence', 'Thomas Jefferson and the Continental Congress', 1776, [
  ('Why does the first paragraph say the colonists should “declare the causes”?', 'Out of respect for the opinions of the rest of the world', ['Because the King asked them to', 'To start a war', 'To make new laws'], '“A decent respect to the opinions of mankind requires that they should declare the causes.”'),
  ('Which three unalienable rights are named?', 'Life, Liberty, and the pursuit of Happiness', ['Food, Shelter, and Clothing', 'Freedom of speech, religion, and the press', 'Property, Voting, and Education'], '“Among these are Life, Liberty, and the pursuit of Happiness.”'),
  ('According to the Declaration, where do governments get their “just powers”?', 'From the consent of the governed', ['From the King', 'From the army', 'From the richest citizens'], 'Governments derive “their just powers from the consent of the governed.”'),
  ('Does the Declaration say governments should be changed for any small reason?', 'No — not for “light and transient causes”', ['Yes, whenever people disagree', 'Yes, every year', 'It does not say'], '“Governments long established should not be changed for light and transient causes.”'),
  ('When do the people have “their duty, to throw off such Government”?', 'After a long train of abuses aimed at absolute tyranny', ['When taxes go up', 'When a leader dies', 'When there is a bad harvest'], '“When a long train of abuses and usurpations … evinces a design to reduce them under absolute Despotism.”'),
])
P('studies', 'bacon', 'STUDIES serve for delight, for ornament, and for ability.', 'chewed and digested;', 'Of Studies', 'Francis Bacon', 1625, [
  ('What three purposes does Bacon say studies serve?', 'Delight, ornament, and ability', ['Money, fame, and power', 'Health, wealth, and wisdom', 'Work, rest, and play'], '“Studies serve for delight, for ornament, and for ability.”'),
  ('What does Bacon say about spending too much time in studies?', 'It is laziness (sloth)', ['It makes you wise', 'It is always good', 'It is dangerous'], '“To spend too much time in studies is sloth.”'),
  ('How should we read, according to Bacon?', 'To weigh and consider', ['To argue against the author', 'To believe everything', 'To find things to talk about'], '“Read not to contradict and confute; nor to believe and take for granted … but to weigh and consider.”'),
  ('What does “Some books are to be tasted, others to be swallowed, and some few to be chewed and digested” mean?', 'Different books deserve different amounts of attention', ['Books are like food', 'Reading makes you hungry', 'You should read while eating'], 'Some deserve only a taste, some a quick read, and “some few to be chewed and digested” — read slowly and thought about.'),
  ('Why does Bacon compare natural abilities to “natural plants”?', 'Both need trimming and shaping — abilities by study', ['Both grow in gardens', 'Both need water', 'Both die in winter'], 'Natural abilities “need proyning, by study.” (Proyning is old spelling of pruning.)'),
])
P('selfreliance', 'emerson', 'A foolish consistency is the hobgoblin of little minds', 'Is it so bad then to be misunderstood?', 'Self-Reliance', 'Ralph Waldo Emerson', 1841, [
  ('What kind of consistency does Emerson criticize?', 'A foolish consistency — refusing to change your mind', ['Being on time', 'Working hard every day', 'Keeping promises'], '“A foolish consistency is the hobgoblin of little minds.”'),
  ('A “hobgoblin” is a mischievous imp. What does the metaphor suggest?', 'Foolish consistency haunts and troubles small minds', ['Little minds are magical', 'Consistency is a fairy tale', 'Small people should be scared'], 'It pictures consistency as a little demon that bothers narrow thinkers.'),
  ('What does Emerson advise you to do “to-morrow”?', 'Say what you think then, even if it contradicts today', ['Repeat what you said today', 'Stay silent', 'Ask others what to think'], '“To-morrow speak what to-morrow thinks in hard words again, though it contradict every thing you said to-day.”'),
  ('How does Emerson answer the worry about being misunderstood?', 'He suggests being misunderstood is not so bad', ['He says you must avoid it', 'He says it never happens', 'He says only fools are misunderstood'], '“Is it so bad then to be misunderstood?”'),
  ('Which statement best sums up the passage?', 'Trust and speak your present thoughts rather than clinging to your past words', ['Always agree with others', 'Never change your opinions', 'Great minds avoid speaking'], 'A great soul has “simply nothing to do” with consistency.'),
])
P('modest', 'swift', 'I have been assured by a very knowing American', 'in a fricasee, or a ragoust.', 'A Modest Proposal', 'Jonathan Swift', 1729, [
  ('What does the speaker seem to propose?', 'Eating the children of the poor', ['Building schools for the poor', 'Sending children to America', 'Giving the poor more food'], 'He calls a well-nursed child “most delicious nourishing and wholesome food.”'),
  ('Did Swift really mean this?', 'No — it is satire that mocks how the poor were treated', ['Yes, he was serious', 'Yes, it was a common recipe', 'Nobody knows'], 'The shocking idea exaggerates how the rich treated the poor as mere resources.'),
  ('What is the effect of the calm, polite tone (“I do … humbly offer”)?', 'It makes the monstrous idea even more shocking', ['It makes the idea sound reasonable to readers', 'It shows Swift was a cook', 'It hides the topic'], 'Treating horror in a businesslike voice is the satire’s sharpest weapon.'),
  ('Why is the title “A Modest Proposal” ironic?', 'The proposal is outrageous, not modest at all', ['It is very short', 'It was published secretly', 'Swift was a modest man'], 'Irony: the words say the opposite of the truth.'),
  ('What is the purpose of satire like this?', 'To expose and criticize a real problem by ridiculing it', ['To give cooking advice', 'To entertain children', 'To describe American food'], 'Swift attacks the cruelty and indifference toward Ireland’s poor.'),
], intro='Ireland, 1729: many families were starving. Swift wrote as a calm “projector” offering a solution.')
P('femalemind', 'wollstonecraft', 'Strengthen the female mind by enlarging it', 'the latter a play-thing.', 'A Vindication of the Rights of Woman', 'Mary Wollstonecraft', 1792, [
  ('What does Wollstonecraft say will end “blind obedience”?', 'Strengthening women’s minds by educating them', ['Giving women more money', 'Letting women stay at home', 'Making new laws for men'], '“Strengthen the female mind by enlarging it, and there will be an end to blind obedience.”'),
  ('Why, according to her, do tyrants want to keep women “in the dark”?', 'Because power always seeks blind obedience', ['Because women prefer it', 'Because education is expensive', 'Because tyrants fear the dark'], '“Blind obedience is ever sought for by power.”'),
  ('“Keep women in the dark” is a metaphor meaning …', 'keep women uneducated and uninformed', ['keep women indoors at night', 'turn off the lights', 'keep secrets from tyrants'], 'Darkness stands for ignorance; light for knowledge.'),
  ('What is the main argument of the passage?', 'Education gives women independence; denying it serves those who want control', ['Women should obey tyrants', 'Men are always tyrants', 'Women do not need education'], 'Educated minds will not obey blindly.'),
], intro='Wollstonecraft argued, in 1792, that women should receive the same education as men.')
P('philosophy', 'russell_problems', 'Philosophy is to be studied, not for the sake of any definite answers', 'which constitutes its highest good.', 'The Problems of Philosophy', 'Bertrand Russell', 1912, [
  ('According to Russell, why should we study philosophy?', 'For the sake of its questions, not definite answers', ['To find final answers to every question', 'To win arguments', 'To pass exams'], 'Philosophy is studied “not for the sake of any definite answers to its questions … but rather for the sake of the questions themselves.”'),
  ('Why does Russell say we cannot study it for definite answers?', 'No definite answers can usually be known to be true', ['The answers are secret', 'Philosophers disagree on spelling', 'The questions are too easy'], '“No definite answers can, as a rule, be known to be true.”'),
  ('How do philosophical questions help us, according to Russell?', 'They enlarge what we think possible and open closed minds', ['They make us certain', 'They make us rich', 'They end all debate'], 'They “enlarge our conception of what is possible” and diminish “dogmatic assurance.”'),
  ('“Dogmatic assurance which closes the mind” describes …', 'being so sure you are right that you stop thinking', ['being polite in debates', 'trusting your teacher', 'feeling safe at home'], 'Dogmatic means insisting on beliefs without being open to question.'),
  ('What is the “highest good” Russell describes?', 'The mind becoming great through contemplating the universe', ['Fame and fortune', 'Winning a debate', 'Knowing every fact'], '“Through the greatness of the universe which philosophy contemplates, the mind also is rendered great.”'),
])
P('mathbeauty', 'russell_mysticism', 'Mathematics, rightly viewed, possesses not only truth, but supreme', 'no barrier to the creative activity', 'The Study of Mathematics (Mysticism and Logic)', 'Bertrand Russell', 1907, [
  ('What does Russell say mathematics has besides truth?', 'Supreme beauty', ['Great usefulness', 'Many rules', 'Endless difficulty'], 'Mathematics “possesses not only truth, but supreme beauty.”'),
  ('To which art does Russell compare the beauty of mathematics?', 'Sculpture — cold and austere', ['Painting — bright and colourful', 'Music — warm and emotional', 'Dance — lively and free'], '“A beauty cold and austere, like that of sculpture.”'),
  ('How does Russell want mathematics to be learned?', 'Not just as a task, but as part of daily thought', ['Only for exams', 'As quickly as possible', 'Only by experts'], 'It should be learnt “not merely … as a task, but to be assimilated as a part of daily thought.”'),
  ('What contrast does Russell draw between real life and pure reason?', 'Life is a compromise; pure reason knows no compromise', ['Life is perfect; reason is messy', 'Both are compromises', 'Neither matters'], '“Real life is, to most men, a long second-best, a perpetual compromise … but the world of pure reason knows no compromise.”'),
  ('Why might a reader find this view surprising?', 'Many people see mathematics as dull calculation, not art', ['Mathematics was invented by artists', 'Russell disliked mathematics', 'Sculpture is a kind of maths'], 'Russell puts mathematics beside poetry: delight “is to be found in mathematics as surely as in poetry.”'),
])
P('elephant', 'orwell_elephant', 'I perceived in this moment that when the white man turns tyrant', 'his face grows to fit it.', 'Shooting an Elephant', 'George Orwell', 1936, [
  ('What does Orwell realize about the ruler who “turns tyrant”?', 'He destroys his own freedom', ['He becomes truly free', 'He gains respect', 'He becomes happy'], '“When the white man turns tyrant it is his own freedom that he destroys.”'),
  ('Why must the colonial officer do what the crowd expects?', 'His rule depends on always appearing strong and impressive', ['He is paid by the crowd', 'The crowd is his family', 'He is afraid of elephants'], '“It is the condition of his rule that he shall spend his life in trying to impress the natives.”'),
  ('What does “He wears a mask, and his face grows to fit it” mean?', 'Pretending to be something long enough changes who you are', ['He wears a costume at work', 'His face is hidden', 'He is an actor'], 'The role he plays slowly becomes his real self.'),
  ('What is the irony Orwell describes?', 'The one who seems to hold power is really controlled by others', ['The elephant is the hero', 'The crowd wants him to leave', 'He enjoys his job'], 'He seems to lead, but must do “what the natives expect of him.”'),
  ('What larger system is Orwell criticizing?', 'Imperialism — one nation ruling another', ['Democracy', 'The police in England', 'Hunting'], 'The essay exposes how colonial rule corrupts the rulers too.'),
], intro='Orwell, a British police officer in colonial Burma (1920s), faces a crowd expecting him to shoot an escaped elephant.')
P('rules', 'orwell_politics', 'I think the following rules will cover most cases:', 'sooner than say anything barbarous.', 'Politics and the English Language', 'George Orwell', 1946, [
  ('According to rule (ii), what should you prefer?', 'A short word over a long one', ['A long word that sounds clever', 'A foreign phrase', 'A scientific term'], '“Never use a long word where a short one will do.”'),
  ('Which sentence follows rule (iv)?', 'The dog chased the ball.', ['The ball was chased by the dog.', 'The ball was chased.', 'It was the ball that was chased by the dog.'], 'Rule (iv): “Never use the passive where you can use the active.”'),
  ('Why does Orwell warn against figures of speech “you are used to seeing in print”?', 'Worn-out phrases replace real thinking', ['Figures of speech are always wrong', 'Printers dislike them', 'They are too new'], 'Stale images are used without thought; fresh language makes you think.'),
  ('What does rule (vi) add to the other rules?', 'Break any rule rather than write something ugly', ['Never break a rule', 'Write as much as possible', 'Use more jargon'], '“Break any of these rules sooner than say anything barbarous.”'),
  ('Which rewrite best follows rule (iii)?', '“I think we should leave.”', ['“I am of the opinion that we should perhaps leave.”', '“It is my considered belief that leaving might be advisable.”', '“In my humble opinion, we ought to consider leaving.”'], 'Rule (iii): “If it is possible to cut a word out, always cut it out.”'),
])
P('morequal', 'orwell_animalfarm', 'For once Benjamin consented to break his rule', 'BUT SOME ANIMALS ARE MORE EQUAL THAN OTHERS', 'Animal Farm', 'George Orwell', 1945, [
  ('What had happened to the Seven Commandments?', 'They had been replaced by a single new commandment', ['They were washed away by rain', 'They were exactly the same', 'They were moved to another barn'], '“There was nothing there now except a single Commandment.”'),
  ('Why is “some animals are more equal than others” a contradiction?', 'Equal means the same — no one can be “more equal”', ['Animals cannot be equal', 'It is spelled wrongly', 'It is a rule about food'], 'The phrase sounds fair but means some rule over others.'),
  ('What does the new commandment reveal about the pigs who rule the farm?', 'They have made themselves the privileged class', ['They want everyone treated the same', 'They have left the farm', 'They cannot read'], 'The pigs twisted the ideal of equality to justify their own power.'),
  ('Why does it matter that Benjamin “consented to break his rule”?', 'Even the silent old donkey now speaks up — the change is that serious', ['Benjamin loves reading aloud', 'Benjamin is the new leader', 'Benjamin wrote the commandment'], 'He usually refuses to get involved, but this time he reads the wall.'),
  ('Animal Farm is an allegory. What does that mean?', 'The story stands for real political events and ideas', ['It is a true story about a farm', 'It is a book of poems', 'It is a science textbook'], 'Orwell used farm animals to criticize how revolutions can turn into tyranny.'),
], intro='The animals once overthrew their human farmer and wrote Seven Commandments, the first of which was that all animals are equal.')
